  'Cinematography is a core Film & Media production course focused on camera, lighting, lensing, movement, color, collaboration, and visual storytelling. Students learn to design images that serve story and performance, operate professional camera and lighting workflows, work safely with crew, communicate with directors and post-production, and develop a polished cinematography portfolio.',
  $cinejson${"slug": "cinematography", "title": "Cinematography", "description": "Cinematography is a core Film & Media production course focused on camera, lighting, lensing, movement, color, collaboration, and visual storytelling. Students learn to design images that serve story and performance, operate professional camera and lighting workflows, work safely with crew, communicate with directors and post-production, and develop a polished cinematography portfolio.", "topics": [{"id": "1d6bcfdc-eb99-4ebc-839c-05254ba88a85", "type": "topic", "title": "Cinematography as Visual Storytelling", "description": "This opening topic defines cinematography as the disciplined design of images in service of story, emotion, rhythm, and audience attention.", "children": [{"id": "71a6c3e9-b015-4426-9713-b5c3479d0935", "type": "subtopic", "title": "The cinematographer's role", "children": [{"id": "9860c57f-9c15-4d6a-95df-3a9ece3738e6", "type": "concept", "title": "Visual authorship and service to the director's vision"}, {"id": "e868ba5b-62db-4a90-bbcb-8e96abd7467a", "type": "concept", "title": "Relationship to production design, costume, editing, and sound"}, {"id": "d0c9e0b7-283a-4c91-b138-acd382d955bb", "type": "concept", "title": "Taste, references, tests, and visual decision-making"}], "description": "Students learn what the DP contributes creatively, technically, and collaboratively."}, {"id": "ca6c5206-fdcc-4baf-adb4-e692aa0282c9", "type": "subtopic", "title": "Image as narrative evidence", "children": [{"id": "84676c0a-0080-4c0f-a097-d26947cca637", "type": "concept", "title": "Mood, theme, character perspective, and point of view"}, {"id": "89291217-248d-4326-978c-8aecd1892b37", "type": "concept", "title": "Visual motifs, contrast, repetition, and transformation"}, {"id": "9605f4cc-c873-4f82-9a66-63a8c7bd4210", "type": "concept", "title": "Reading cinematography in existing films"}], "description": "The goal is to treat every frame as a story choice."}, {"id": "29ee727f-9783-420d-849b-ef5e5344a62e", "type": "subtopic", "title": "Production constraints as creative tools", "children": [{"id": "cc2b4f57-fa31-4966-be85-052624913f07", "type": "concept", "title": "Budget, time, location, crew, and gear limits"}, {"id": "f0275cdb-69c3-4e5a-8a23-98387d026524", "type": "concept", "title": "Designing images around available resources"}, {"id": "4aeb4943-edf2-4ade-965b-f6c7572b3044", "type": "concept", "title": "Problem-solving without sacrificing intention"}], "description": "Students learn that limitations often generate style."}]}, {"id": "efa9b061-65c2-41e5-918f-f80c3b428141", "type": "topic", "title": "Camera Systems and Set Workflow", "description": "This topic gives students operational confidence with cameras while emphasizing professional workflow and reliability.", "children": [{"id": "c47e4e85-e79c-4a98-8e9d-ccd3fee8801d", "type": "subtopic", "title": "Camera bodies and formats", "children": [{"id": "724f06a5-d75a-4894-9702-d8054b1e1f78", "type": "concept", "title": "Digital cinema, mirrorless, broadcast, and smartphone systems"}, {"id": "58600d83-7fc6-43a6-89cf-f38efc6b7e62", "type": "concept", "title": "Sensor size, resolution, rolling shutter, and dynamic range"}, {"id": "36d6a286-4d60-4e9a-b46a-27281616c990", "type": "concept", "title": "Media, power, monitoring, and accessories"}], "description": "Students learn how camera choice shapes image, workflow, and production logistics."}, {"id": "fc304981-55d5-4571-8ce5-33b0afca6899", "type": "subtopic", "title": "Menus, monitoring, and exposure tools", "children": [{"id": "d575f11e-cabc-4119-8493-bed296694d59", "type": "concept", "title": "Waveform, false color, histogram, zebras, and focus peaking"}, {"id": "5a288751-92e5-41bc-b774-d80d01b703cd", "type": "concept", "title": "Frame guides, LUT monitoring, and display calibration"}, {"id": "f495610c-6520-41fa-a006-a73417f5a2cb", "type": "concept", "title": "Metadata, clip naming, and media management"}], "description": "The point is to