update public.learning_paths
set
  title = 'Cinematography',
  goal = 'Cinematography',
  summary = 'Cinematography is a core Film & Media production course focused on camera, lighting, lensing, movement, color, collaboration, and visual storytelling. Students learn to design images that serve story and performance, operate professional camera and lighting workflows, work safely with crew, communicate with directors and post-production, and develop a polished cinematography portfolio.',
  data = $cinejson${"slug": "cinematography", "title": "Cinematography", "description": "Cinematography is a core Film & Media production course focused on camera, lighting, lensing, movement, color, collaboration, and visual storytelling. Students learn to design images that serve story and performance, operate professional camera and lighting workflows, work safely with crew, communicate with directors and post-production, and develop a polished cinematography portfolio.", "topics": [{"id": "1d6bcfdc-eb99-4ebc-839c-05254ba88a85", "type": "topic", "title": "Cinematography as Visual Storytelling", "description": "This opening topic defines cinematography as the disciplined design of images in service of story, emotion, rhythm, and audience attention.", "children": [{"id": "71a6c3e9-b015-4426-9713-b5c3479d0935", "type": "subtopic", "title": "The cinematographer's role", "children": [{"id": "9860c57f-9c15-4d6a-95df-3a9ece3738e6", "type": "concept", "title": "Visual authorship and service to the director's vision"}, {"id": "e868ba5b-62db-4a90-bbcb-8e96abd7467a", "type": "concept", "title": "Relationship to production design, costume, editing, and sound"}, {"id": "d0c9e0b7-283a-4c91-b138-acd382d955bb", "type": "concept", "title": "Taste, references, tests, and visual decision-making"}], "description": "Students learn what the DP contributes creatively, technically, and collaboratively."}, {"id": "ca6c5206-fdcc-4baf-adb4-e692aa0282c9", "type": "subtopic", "title": "Image as narrative evidence", "children": [{"id": "84676c0a-0080-4c0f-a097-d26947cca637", "type": "concept", "title": "Mood, theme, character perspective, and point of view"}, {"id": "89291217-248d-4326-978c-8aecd1892b37", "type": "concept", "title": "Visual motifs, contrast, repetition, and transformation"}, {"id": "9605f4cc-c873-4f82-9a66-63a8c7bd4210", "type": "concept", "title": "Reading cinematography in existing films"}], "description": "The goal is to treat every frame as a story choice."}, {"id": "29ee727f-9783-420d-849b-ef5e5344a62e", "type": "subtopic", "title": "Production constraints as creative tools", "children": [{"id": "cc2b4f57-fa31-4966-be85-052624913f07", "type": "concept", "title": "Budget, time, location, crew, and gear limits"}, {"id": "f0275cdb-69c3-4e5a-8a23-98387d026524", "type": "concept", "title": "Designing images around available resources"}, {"id": "4aeb4943-edf2-4ade-965b-f6c7572b3044", "type": "concept", "title": "Problem-solving without sacrificing intention"}], "description": "Students learn that limitations often generate style."}]}, {"id": "efa9b061-65c2-41e5-918f-f80c3b428141", "type": "topic", "title": "Camera Systems and Set Workflow", "description": "This topic gives students operational confidence with cameras while emphasizing professional workflow and reliability.", "children": [{"id": "c47e4e85-e79c-4a98-8e9d-ccd3fee8801d", "type": "subtopic", "title": "Camera bodies and formats", "children": [{"id": "724f06a5-d75a-4894-9702-d8054b1e1f78", "type": "concept", "title": "Digital cinema, mirrorless, broadcast, and smartphone systems"}, {"id": "58600d83-7fc6-43a6-89cf-f38efc6b7e62", "type": "concept", "title": "Sensor size, resolution, rolling shutter, and dynamic range"}, {"id": "36d6a286-4d60-4e9a-b46a-27281616c990", "type": "concept", "title": "Media, power, monitoring, and accessories"}], "description": "Students learn how camera choice shapes image, workflow, and production logistics."}, {"id": "fc304981-55d5-4571-8ce5-33b0afca6899", "type": "subtopic", "title": "Menus, monitoring, and exposure tools", "children": [{"id": "d575f11e-cabc-4119-8493-bed296694d59", "type": "concept", "title": "Waveform, false color, histogram, zebras, and focus peaking"}, {"id": "5a288751-92e5-41bc-b774-d80d01b703cd", "type": "concept", "title": "Frame guides, LUT monitoring, and display calibration"}, {"id": "f495610c-6520-41fa-a006-a73417f5a2cb", "type": "concept", "title": "Metadata, clip naming, and media management"}], "description": "The point is to use camera tools deliberately rather than by habit."}, {"id": "37e8317b-7990-4691-8e11-bac2cb5df63c", "type": "subtopic", "title": "On-set workflow discipline", "children": [{"id": "5a25de61-3518-44ae-aeaf-3044e718a642", "type": "concept", "title": "Camera reports, slating, cards, backups, and checksums"}, {"id": "70929376-0d02-47b4-abbb-fa8ae7bee108", "type": "concept", "title": "Communication with assistant camera, DIT, script supervisor, and editor"}, {"id": "fc4d8f77-177e-4e48-921d-76ec33cad12a", "type": "concept", "title": "Resetting, labeling, and troubleshooting under pressure"}], "description": "Students practice habits that protect footage and time."}]}, {"id": "05e0969d-fd6c-4bf3-a1ae-a5fb19b78ef7", "type": "topic", "title": "Lens Fundamentals and Optical Choices", "description": "Lenses are expressive instruments, not just magnification tools. This topic connects focal length, perspective, depth, texture, and character psychology.", "children": [{"id": "4ee0254c-6a7a-4fa9-85ff-b4a26d64bd28", "type": "subtopic", "title": "Focal length and perspective", "children": [{"id": "ef269306-6ad2-4bdc-a9ec-5ca8bd30938b", "type": "concept", "title": "Wide, normal, telephoto, macro, and specialty lenses"}, {"id": "39a7e193-e41a-4fb2-96d0-f04debd80ba8", "type": "concept", "title": "Compression, distortion, and proximity"}, {"id": "8eec4c89-9e93-4e9f-a0c9-63ca21d1331c", "type": "concept", "title": "Matching lens choice to scene intent"}], "description": "Students learn how lens choice changes spatial relationships and emotional distance."}, {"id": "4636f9c5-9f51-4bf3-a9c5-a0e517e2e47a", "type": "subtopic", "title": "Aperture, focus, and depth of field", "children": [{"id": "171bcd2e-db6c-4a50-b95c-1703e1f33170", "type": "concept", "title": "T-stops, f-stops, bokeh, close focus, and hyperfocal distance"}, {"id": "daa90493-1e2c-4798-a3d3-3be2c8334cd0", "type": "concept", "title": "Rack focus, split focus, and focus pulls"}, {"id": "3972dfd0-1ab3-4456-8eb4-b1fbd52a046b", "type": "concept", "title": "Depth as a dramatic and spatial device"}], "description": "The gist is to control attention through sharpness and blur."}, {"id": "c352cd67-f9b0-402c-9050-72dc9979777e", "type": "subtopic", "title": "Lens character and testing", "children": [{"id": "b6243624-50ac-40d7-a8dc-fcb93a3fdb1a", "type": "concept", "title": "Sharpness, contrast, flare, breathing, color, and aberration"}, {"id": "7b2a1e50-30a7-4bd4-a8ff-d7077b283cd4", "type": "concept", "title": "Prime versus zoom workflow"}, {"id": "1051622b-7dad-47f3-bcb1-8ba8108dc963", "type": "concept", "title": "Lens tests, charts, and subjective look evaluation"}], "description": "Students learn to evaluate lenses before relying on them."}]}, {"id": "bdf338f2-46fa-46d6-a15b-229b1777a01b", "type": "topic", "title": "Exposure, Dynamic Range, and the Digital Image", "description": "This topic teaches students how exposure decisions shape mood, texture, recoverability, and post-production flexibility.", "children": [{"id": "39d00b60-6e11-4c53-87d5-6eed196f530e", "type": "subtopic", "title": "The exposure triangle", "children": [{"id": "a6b1dd66-f8fc-4858-ba13-d43f1fc4757c", "type": "concept", "title": "ISO, EI, shutter angle, aperture, ND filtration"}, {"id": "056a07dc-5424-4cb7-989d-1c842d732648", "type": "concept", "title": "Motion blur, noise, and depth-of-field tradeoffs"}, {"id": "3f4f82fa-8dbe-4b7b-affc-bc2195c81208", "type": "concept", "title": "Manual exposure discipline"}], "description": "Students learn the practical relationship among aperture, shutter, and sensitivity."}, {"id": "393b50a0-3fb6-4069-a858-553ba1efe87a", "type": "subtopic", "title": "Dynamic range and latitude", "children": [{"id": "e294b6d8-fcc1-48f0-b627-3f5c6733af69", "type": "concept", "title": "Stops, clipping, noise floor, and middle gray"}, {"id": "535ad3c5-548f-49f0-bae4-60b1f96e5f36", "type": "concept", "title": "Log, raw, and baked image profiles"}, {"id": "80b519ab-81e0-49ca-8a4e-c5ad109a30e3", "type": "concept", "title": "Expose-to-the-right debates and production context"}], "description": "The point is to protect highlights, shadows, and skin tones."}, {"id": "c64e7079-9190-4b0f-a67a-8853c4d53011", "type": "subtopic", "title": "Measuring and controlling exposure", "children": [{"id": "25a8423a-60fc-409e-8160-0c91f996f495", "type": "concept", "title": "Incident and spot metering"}, {"id": "46268740-9bd6-43a6-a1f2-ad4cf2fd709d", "type": "concept", "title": "Waveform and false-color interpretation"}, {"id": "be9afdc3-1585-472a-babb-23bd2083c8ea", "type": "concept", "title": "Exposure consistency across coverage"}], "description": "Students connect meters and scopes to creative judgment."}]}, {"id": "157ccd75-bee7-416e-88ed-72d81628e71c", "type": "topic", "title": "Composition and Framing", "description": "Composition organizes attention inside the frame. This topic builds the visual literacy needed to make frames legible, expressive, and cinematic.", "children": [{"id": "feef199c-0d6a-4608-a779-dd5662bce0b3", "type": "subtopic", "title": "Frame geometry", "children": [{"id": "f515e4da-ab18-4cef-9317-8f194975718e", "type": "concept", "title": "Rule of thirds, symmetry, asymmetry, and center framing"}, {"id": "d6f61402-2670-46b4-9291-2fd3c71b7be6", "type": "concept", "title": "Leading lines, frames within frames, and layered depth"}, {"id": "0cc60ea3-ed48-4366-ac79-a4e32e5d3549", "type": "concept", "title": "Headroom, look room, eyelines, and screen direction"}], "description": "Students learn to compose through balance, line, shape, depth, and negative space."}, {"id": "ceaf8097-721e-42b3-b028-0e1b3a57aa72", "type": "subtopic", "title": "Aspect ratio and format", "children": [{"id": "e450662d-9fc5-4c1e-b6a5-8594f14960c4", "type": "concept", "title": "1.33, 1.66, 1.85, 2.39, vertical, square, and social formats"}, {"id": "5b8d0fca-2698-4673-8778-40d14d57e0f2", "type": "concept", "title": "Safe areas, reframing, and platform delivery"}, {"id": "c5d04337-34ec-4e80-bab4-88fc395e0801", "type": "concept", "title": "How aspect ratio changes blocking and staging"}], "description": "The goal is to design images for the chosen canvas."}, {"id": "2fc5c5ff-aacd-4a5d-9600-7ec702676952", "type": "subtopic", "title": "Composition for meaning", "children": [{"id": "fbcf07d4-9ff5-4b41-b100-68376ad718b3", "type": "concept", "title": "Power, isolation, intimacy, tension, and reveal"}, {"id": "4c65d808-45a9-4ef1-a2bd-e58f8a8afab2", "type": "concept", "title": "Subject-object relationships"}, {"id": "c3155f18-82b7-4c42-985b-348d6aac7725", "type": "concept", "title": "Foreground and background as story information"}], "description": "Students practice using framing as subtext."}]}, {"id": "b82ba40b-dac5-49ef-84f0-7d0c462192d6", "type": "topic", "title": "Camera Movement and Stabilization", "description": "Movement changes how viewers feel space and time. This topic teaches when to move, how to move, and when stillness is stronger.", "children": [{"id": "6026c5bb-f26f-4e96-81be-e428082e2a11", "type": "subtopic", "title": "Movement motivation", "children": [{"id": "0c89533d-3969-4beb-8ab9-8c2d6625e0d3", "type": "concept", "title": "Character movement, emotional shift, reveal, pursuit, and discovery"}, {"id": "5e3f507a-1758-44f8-a530-d9b4fd1dbc4f", "type": "concept", "title": "Stillness, drift, push, pull, pan, tilt, track, crane, and handheld"}, {"id": "eadfd15e-75a1-48ce-b60a-f602f4e0a219", "type": "concept", "title": "Rhythm and editorial consequences"}], "description": "Students learn to connect camera movement to story rather than decoration."}, {"id": "bac52198-65b2-49fb-84eb-17a51e8e3044", "type": "subtopic", "title": "Tools and techniques", "children": [{"id": "dfc63f9c-f6a7-4c45-ad1e-99cb8d1a8ff7", "type": "concept", "title": "Tripod, dolly, slider, jib, crane, Steadicam, gimbal, drone, vehicle rigs"}, {"id": "6f3a2daf-cfef-4899-926d-654f28303ebc", "type": "concept", "title": "Handheld posture and controlled instability"}, {"id": "5fc1fc64-abb2-41eb-aae2-e630fe89ec3e", "type": "concept", "title": "Safety, rehearsal, marks, and repeatability"}], "description": "The point is to understand movement options and their tradeoffs."}, {"id": "a14a7473-374f-478d-a6f8-121ec7a82f15", "type": "subtopic", "title": "Movement grammar", "children": [{"id": "c9bbb893-f412-4534-a85d-0f4a10399683", "type": "concept", "title": "Axis, screen direction, motivated reframing, and parallax"}, {"id": "65354446-fe3b-47d9-bd9a-33fcb4162316", "type": "concept", "title": "Long takes and blocking complexity"}, {"id": "7d22a642-19c0-46fd-9b92-3ab9a82a9e35", "type": "concept", "title": "Cutting into and out of movement"}], "description": "Students learn how motion affects continuity and audience orientation."}]}, {"id": "74acddd8-3e96-4eac-8b8d-88b8f61a8bd3", "type": "topic", "title": "Light Physics, Fixtures, and Safety", "description": "Before expressive lighting, students need the fundamentals of light behavior, fixture choice, power, and safe set practice.", "children": [{"id": "db1f0266-f6d7-4602-a040-c45207ba3c42", "type": "subtopic", "title": "Light behavior", "children": [{"id": "e77a6d69-c6a9-4aed-8aa6-5ae5c0cb421f", "type": "concept", "title": "Intensity, distance, inverse square law, spread, falloff, and direction"}, {"id": "2f1431ab-51a9-4c1b-8661-8ef3cda462ae", "type": "concept", "title": "Hardness, softness, diffusion, bounce, and negative fill"}, {"id": "47ceba27-e4bf-4a53-9f09-95282486f1c0", "type": "concept", "title": "Reflection, absorption, transmission, and color temperature"}], "description": "Students learn the physics that makes lighting predictable."}, {"id": "506d47b6-5df6-4a3b-a449-eb2ae35f748b", "type": "subtopic", "title": "Lighting units and control", "children": [{"id": "96f27cc2-139f-4021-a409-b4b75ed6d19e", "type": "concept", "title": "LED, tungsten, HMI, fluorescent, practicals, tubes, panels, and fresnels"}, {"id": "1ffba21a-1774-4c7d-b853-80de49e41fa4", "type": "concept", "title": "Flags, nets, scrims, grids, cutters, diffusion, and gels"}, {"id": "f3584ce1-e31a-46f8-bb78-20e46bb8d507", "type": "concept", "title": "DMX, dimming, flicker, and fixture limitations"}], "description": "The gist is to know what tools do before placing them."}, {"id": "164b76ae-c66f-4d09-9d54-19f370af06e0", "type": "subtopic", "title": "Electrical and set safety", "children": [{"id": "1a785aa8-9a49-44eb-8311-edbf061a7504", "type": "concept", "title": "Load calculations, circuits, batteries, cabling, and weather"}, {"id": "c25bbe85-ed91-470b-aabf-fc397750dad1", "type": "concept", "title": "Grip stands, sandbags, overhead rigging, and hot fixtures"}, {"id": "83daf691-692a-4bbe-a65f-0f78214b02cc", "type": "concept", "title": "Set communication and hazard awareness"}], "description": "Students learn professional habits that prevent injury and equipment failure."}]}, {"id": "e6376ca8-c535-48b5-9f8c-cc37c564ca1a", "type": "topic", "title": "Lighting for Mood, Faces, and Story", "description": "Lighting is where cinematography becomes emotional architecture. This topic trains students to shape faces, spaces, contrast, and atmosphere.", "children": [{"id": "e9292f38-8093-4a25-98d5-73a0a32f5967", "type": "subtopic", "title": "Key, fill, backlight, and contrast", "children": [{"id": "db604560-f3f8-49ff-97b2-8493e1de97a4", "type": "concept", "title": "Three-point lighting and its alternatives"}, {"id": "f99163bb-3f8b-46bc-8e6b-2315d748b7dd", "type": "concept", "title": "Lighting ratios, mood, and genre conventions"}, {"id": "bd908522-ba61-452c-970a-d6dd88b7fea8", "type": "concept", "title": "Silhouette, edge light, toppers, eye light, and wrap"}], "description": "Students learn classic lighting structure as a flexible language."}, {"id": "b2f7f08b-2bdb-4450-9194-c37719f46114", "type": "subtopic", "title": "Lighting faces and skin", "children": [{"id": "2f18c65f-059a-4d46-8ee7-567ffb9c5b8f", "type": "concept", "title": "Face shape, skin tone, texture, age, and makeup"}, {"id": "02e8516b-ec66-426f-ba21-458f52c5470e", "type": "concept", "title": "Soft versus hard sources and directionality"}, {"id": "5b4a4b61-b512-4c36-a183-5fb4c7bd5ae0", "type": "concept", "title": "Exposure choices that respect subject dignity"}], "description": "The point is to make ethical and beautiful choices across different people and contexts."}, {"id": "798456e2-df3b-4e14-bda2-e682720a5f3b", "type": "subtopic", "title": "Atmosphere and motivated light", "children": [{"id": "512dddec-1d30-4bd8-94a8-525d700c9b16", "type": "concept", "title": "Windows, lamps, screens, signs, fire, moonlight, and streetlight"}, {"id": "65386bab-097b-4500-b4f9-f7e2ca18bf2c", "type": "concept", "title": "Smoke, haze, rain, and texture"}, {"id": "9a7d3a48-098b-4bce-9be1-b216a7366c08", "type": "concept", "title": "Day, night, dawn, dusk, and continuity across time"}], "description": "Students connect light to the world of the scene."}]}, {"id": "d69b6270-c4de-4453-ada7-362200f4e95d", "type": "topic", "title": "Color, Contrast, and Visual Palette", "description": "Color and contrast carry emotion, time, genre, and world-building. This topic links on-set color decisions to post-production and story design.", "children": [{"id": "6b9e2e7e-81f2-4bb0-95ad-9160bc562333", "type": "subtopic", "title": "Color theory for cinematography", "children": [{"id": "2aea0606-083c-495b-9f36-d8d5a124125a", "type": "concept", "title": "Complementary, analogous, monochrome, and split palettes"}, {"id": "86ec7932-dee5-4271-9b61-feb882aea857", "type": "concept", "title": "Warm/cool contrast and emotional associations"}, {"id": "93758b3a-7688-469c-9031-ca37e88c0513", "type": "concept", "title": "Color scripts and palette boards"}], "description": "Students learn the visual effects of hue, saturation, value, and temperature."}, {"id": "ae7951f3-71f6-4bfd-b657-46dfb6310544", "type": "subtopic", "title": "White balance and color management", "children": [{"id": "454eed82-655e-4636-9b57-e529d7d072e5", "type": "concept", "title": "Kelvin settings, tint, mixed sources, and gels"}, {"id": "3ee4d52f-a887-4250-8385-da5541337bce", "type": "concept", "title": "Log, LUTs, transforms, ACES concepts, and display-referred images"}, {"id": "58680394-b23b-48ac-aea8-62020346785e", "type": "concept", "title": "Color charts and controlled references"}], "description": "The goal is to maintain control from camera to grade."}, {"id": "e14cb9b5-248f-4b12-80f1-ab2ad4acccbe", "type": "subtopic", "title": "Contrast and tonal design", "children": [{"id": "2ee7076f-3195-4f06-90c7-539f3f4e52a9", "type": "concept", "title": "High key, low key, noir, naturalism, and stylization"}, {"id": "1acff3a8-c33d-4310-945e-1f857857e105", "type": "concept", "title": "Black levels, highlight rolloff, and skin-tone placement"}, {"id": "f84218bf-72fc-49c4-890d-fac9c5b76321", "type": "concept", "title": "Matching contrast across coverage"}], "description": "Students understand tone as composition."}]}, {"id": "9ea2739a-f67c-4ee6-91bb-ae1e68e0e124", "type": "topic", "title": "Blocking, Coverage, and Director Collaboration", "description": "Great images emerge from performance, staging, and collaboration. This topic teaches students to build shots with directors and actors rather than merely record action.", "children": [{"id": "d50a8442-1adf-4a7f-a0aa-94c71c3327b5", "type": "subtopic", "title": "Blocking with story intent", "children": [{"id": "0d11c213-6d68-4123-8cb1-d845ac6c45a4", "type": "concept", "title": "Power shifts, entrances, exits, proximity, and reveal"}, {"id": "38b960be-03fb-4f95-b1f5-deaac70e8869", "type": "concept", "title": "Camera position relative to performance"}, {"id": "665e6541-a0b0-4e42-8ae4-475814a688f1", "type": "concept", "title": "Rehearsal as image discovery"}], "description": "Students learn to place camera and actors around dramatic beats."}, {"id": "6b679fff-3d33-49e6-b2a9-0bb6be018387", "type": "subtopic", "title": "Coverage strategy", "children": [{"id": "b0269957-f33b-4b6c-a610-61bf800c45e2", "type": "concept", "title": "Masters, singles, over-the-shoulders, inserts, and cutaways"}, {"id": "6baa29f4-fb6f-42f4-b4af-24a391ff8eaf", "type": "concept", "title": "Shot size progression and emotional escalation"}, {"id": "2e518d27-af33-4581-97ba-abffe44de9bd", "type": "concept", "title": "Efficiency versus expressive specificity"}], "description": "The point is to design shots that edit together and preserve performance."}, {"id": "b9be123c-719d-4c3d-9e3e-581bdd290dd9", "type": "subtopic", "title": "Director-DP communication", "children": [{"id": "29544d63-12f4-49e5-b823-92c50b1b6fe6", "type": "concept", "title": "Lookbooks, references, shot lists, overheads, and tests"}, {"id": "191688a5-0ccc-44a9-aa8a-440fb723a8bf", "type": "concept", "title": "Language for mood, lens, movement, and light"}, {"id": "4d92bcbf-094b-45cf-8021-9b5eb5248be1", "type": "concept", "title": "Negotiating creative priorities under constraints"}], "description": "Students practice translating ideas into shootable plans."}]}, {"id": "999baf68-1fae-48f3-b39e-8be20bf36f2c", "type": "topic", "title": "Location, Interior, and Exterior Lighting Practice", "description": "This topic moves students from theory into repeatable setups under real location constraints.", "children": [{"id": "6df7ffe3-e6da-4555-bf2a-323d7e9c6352", "type": "subtopic", "title": "Interior lighting setups", "children": [{"id": "0f4b5327-234d-4bfc-bae5-527c9fbe896a", "type": "concept", "title": "Window key, practical augmentation, book lights, negative fill"}, {"id": "73c046a6-902e-40ed-8b07-1c314d749f9a", "type": "concept", "title": "Small room strategy and spill control"}, {"id": "401ca673-5587-4405-925f-5240d02e64ff", "type": "concept", "title": "Continuity across coverage"}], "description": "Students practice building motivated interiors quickly and safely."}, {"id": "6b6bf8bd-7cd2-46c2-917b-ed20fd3a1acd", "type": "subtopic", "title": "Exterior lighting setups", "children": [{"id": "4d27e9ab-3f51-48a0-b5d2-7064dad70fe1", "type": 