  ('6026c5bb-f26f-4e96-81be-e428082e2a11', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'b82ba40b-dac5-49ef-84f0-7d0c462192d6', 'subtopic'::public.curated_course_node_type, 'Movement motivation', 'Students learn to connect camera movement to story rather than decoration.', 0),
  ('0c89533d-3969-4beb-8ab9-8c2d6625e0d3', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '6026c5bb-f26f-4e96-81be-e428082e2a11', 'concept'::public.curated_course_node_type, 'Character movement, emotional shift, reveal, pursuit, and discovery', null, 0),
  ('5e3f507a-1758-44f8-a530-d9b4fd1dbc4f', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '6026c5bb-f26f-4e96-81be-e428082e2a11', 'concept'::public.curated_course_node_type, 'Stillness, drift, push, pull, pan, tilt, track, crane, and handheld', null, 1),
  ('eadfd15e-75a1-48ce-b60a-f602f4e0a219', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '6026c5bb-f26f-4e96-81be-e428082e2a11', 'concept'::public.curated_course_node_type, 'Rhythm and editorial consequences', null, 2),
  ('bac52198-65b2-49fb-84eb-17a51e8e3044', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'b82ba40b-dac5-49ef-84f0-7d0c462192d6', 'subtopic'::public.curated_course_node_type, 'Tools and techniques', 'The point is to understand movement options and their tradeoffs.', 1),
  ('dfc63f9c-f6a7-4c45-ad1e-99cb8d1a8ff7', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'bac52198-65b2-49fb-84eb-17a51e8e3044', 'concept'::public.curated_course_node_type, 'Tripod, dolly, slider, jib, crane, Steadicam, gimbal, drone, vehicle rigs', null, 0),
  ('6f3a2daf-cfef-4899-926d-654f28303ebc', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'bac52198-65b2-49fb-84eb-17a51e8e3044', 'concept'::public.curated_course_node_type, 'Handheld posture and controlled instability', null, 1),
  ('5fc1fc64-abb2-41eb-aae2-e630fe89ec3e', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'bac52198-65b2-49fb-84eb-17a51e8e3044', 'concept'::public.curated_course_node_type, 'Safety, rehearsal, marks, and repeatability', null, 2),
  ('a14a7473-374f-478d-a6f8-121ec7a82f15', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'b82ba40b-dac5-49ef-84f0-7d0c462192d6', 'subtopic'::public.curated_course_node_type, 'Movement grammar', 'Students learn how motion affects continuity and audience orientation.', 2),
  ('c9bbb893-f412-4534-a85d-0f4a10399683', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'a14a7473-374f-478d-a6f8-121ec7a82f15', 'concept'::public.curated_course_node_type, 'Axis, screen direction, motivated reframing, and parallax', null, 0),
  ('65354446-fe3b-47d9-bd9a-33fcb4162316', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'a14a7473-374f-478d-a6f8-121ec7a82f15', 'concept'::public.curated_course_node_type, 'Long takes and blocking complexity', null, 1),
  ('7d22a642-19c0-46fd-9b92-3ab9a82a9e35', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'a14a7473-374f-478d-a6f8-121ec7a82f15', 'concept'::public.curated_course_node_type, 'Cutting into and out of movement', null, 2),
  ('74acddd8-3e96-4eac-8b8d-88b8f61a8bd3', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', null, 'topic'::public.curated_course_node_type, 'Light Physics, Fixtures, and Safety', 'Before expressive lighting, students need the fundamentals of light behavior, fixture choice, power, and safe set practice.', 6),
  ('db1f0266-f6d7-4602-a040-c45207ba3c42', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '74acddd8-3e96-4eac-8b8d-88b8f61a8bd3', 'subtopic'::public.curated_course_node_type, 'Light behavior', 'Students learn the physics that makes lighting predictable.', 0);
