  ('164b76ae-c66f-4d09-9d54-19f370af06e0', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '74acddd8-3e96-4eac-8b8d-88b8f61a8bd3', 'subtopic'::public.curated_course_node_type, 'Electrical and set safety', 'Students learn professional habits that prevent injury and equipment failure.', 2),
  ('1a785aa8-9a49-44eb-8311-edbf061a7504', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '164b76ae-c66f-4d09-9d54-19f370af06e0', 'concept'::public.curated_course_node_type, 'Load calculations, circuits, batteries, cabling, and weather', null, 0),
  ('c25bbe85-ed91-470b-aabf-fc397750dad1', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '164b76ae-c66f-4d09-9d54-19f370af06e0', 'concept'::public.curated_course_node_type, 'Grip stands, sandbags, overhead rigging, and hot fixtures', null, 1),
  ('83daf691-692a-4bbe-a65f-0f78214b02cc', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '164b76ae-c66f-4d09-9d54-19f370af06e0', 'concept'::public.curated_course_node_type, 'Set communication and hazard awareness', null, 2),
  ('e6376ca8-c535-48b5-9f8c-cc37c564ca1a', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', null, 'topic'::public.curated_course_node_type, 'Lighting for Mood, Faces, and Story', 'Lighting is where cinematography becomes emotional architecture. This topic trains students to shape faces, spaces, contrast, and atmosphere.', 7),
