  ('db604560-f3f8-49ff-97b2-8493e1de97a4', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e9292f38-8093-4a25-98d5-73a0a32f5967', 'concept'::public.curated_course_node_type, 'Three-point lighting and its alternatives', null, 0),
  ('f99163bb-3f8b-46bc-8e6b-2315d748b7dd', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e9292f38-8093-4a25-98d5-73a0a32f5967', 'concept'::public.curated_course_node_type, 'Lighting ratios, mood, and genre conventions', null, 1),
  ('bd908522-ba61-452c-970a-d6dd88b7fea8', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e9292f38-8093-4a25-98d5-73a0a32f5967', 'concept'::public.curated_course_node_type, 'Silhouette, edge light, toppers, eye light, and wrap', null, 2),
  ('b2f7f08b-2bdb-4450-9194-c37719f46114', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e6376ca8-c535-48b5-9f8c-cc37c564ca1a', 'subtopic'::public.curated_course_node_type, 'Lighting faces and skin', 'The point is to make ethical and beautiful choices across different people and contexts.', 1),
  ('2f18c65f-059a-4d46-8ee7-567ffb9c5b8f', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'b2f7f08b-2bdb-4450-9194-c37719f46114', 'concept'::public.curated_course_node_type, 'Face shape, skin tone, texture, age, and makeup', null, 0),
