  ('798456e2-df3b-4e14-bda2-e682720a5f3b', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e6376ca8-c535-48b5-9f8c-cc37c564ca1a', 'subtopic'::public.curated_course_node_type, 'Atmosphere and motivated light', 'Students connect light to the world of the scene.', 2),
  ('512dddec-1d30-4bd8-94a8-525d700c9b16', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '798456e2-df3b-4e14-bda2-e682720a5f3b', 'concept'::public.curated_course_node_type, 'Windows, lamps, screens, signs, fire, moonlight, and streetlight', null, 0),
  ('65386bab-097b-4500-b4f9-f7e2ca18bf2c', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '798456e2-df3b-4e14-bda2-e682720a5f3b', 'concept'::public.curated_course_node_type, 'Smoke, haze, rain, and texture', null, 1),
  ('9a7d3a48-098b-4bce-9be1-b216a7366c08', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '798456e2-df3b-4e14-bda2-e682720a5f3b', 'concept'::public.curated_course_node_type, 'Day, night, dawn, dusk, and continuity across time', null, 2),
