  ('2aea0606-083c-495b-9f36-d8d5a124125a', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '6b9e2e7e-81f2-4bb0-95ad-9160bc562333', 'concept'::public.curated_course_node_type, 'Complementary, analogous, monochrome, and split palettes', null, 0),
