  ('93758b3a-7688-469c-9031-ca37e88c0513', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', '6b9e2e7e-81f2-4bb0-95ad-9160bc562333', 'concept'::public.curated_course_node_type, 'Color scripts and palette boards', null, 2),
  ('ae7951f3-71f6-4bfd-b657-46dfb6310544', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'd69b6270-c4de-4453-ada7-362200f4e95d', 'subtopic'::public.curated_course_node_type, 'White balance and color management', 'The goal is to maintain control from camera to grade.', 1),
