  ('2ee7076f-3195-4f06-90c7-539f3f4e52a9', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e14cb9b5-248f-4b12-80f1-ab2ad4acccbe', 'concept'::public.curated_course_node_type, 'High key, low key, noir, naturalism, and stylization', null, 0),
  ('1acff3a8-c33d-4310-945e-1f857857e105', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e14cb9b5-248f-4b12-80f1-ab2ad4acccbe', 'concept'::public.curated_course_node_type, 'Black levels, highlight rolloff, and skin-tone placement', null, 1),
  ('f84218bf-72fc-49c4-890d-fac9c5b76321', 'c7d8e9f0-1a2b-4c42-9e12-2f3a4b5c6d42', 'e14cb9b5-248f-4b12-80f1-ab2ad4acccbe', 'concept'::public.curated_course_node_type, 'Matching contrast across coverage', null, 2),
